var a=`1031-canh-chua`;var n=`world-1031`;var t=`VN`;var s=`southeast-asia`;var r=4;var o=34;var h={en:`Canh Chua`,ua:`Кань чуа`};var g={en:`Canh Chua is a dish from Vietnam prepared with tamarind concentrate, lemongrass, tilapia, pineapple. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Кань чуа, страва кухні країни В'єтнам, яку готують із таких продуктів: концентрат тамаринду, лемонграс, тилапія, ананас. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 15 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 15 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:15,i:[[`fish-stock`,900,`ml`],[`tamarind-concentrate`,35,`g`],[`lemongrass`,20,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 12 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 12 хвилин до готовності й м’якості.`,t:[`poaching`],m:12,i:[[`tilapia`,540,`g`],[`pineapple`,250,`g`],[`tomato`,200,`g`],[`okra`,160,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`fish-sauce`,38,`ml`],[`white-granulated-sugar`,15,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`bean-sprouts`,130,`g`],[`cilantro`,25,`g`]]}];var d={slug:a,id:n,country:`VN`,region:s,servings:4,minutes:34,title:h,text:g,steps:m};export{t as country,d as default,n as id,o as minutes,s as region,r as servings,a as slug,m as steps,g as text,h as title};